INSERT INTO historia_idioma (hiid_titulo, hiid_legenda_imagem, hiid_texto, hist_id, idio_id) VALUES
('Iara: a Mãe da Água', 'Legenda: Sereia Iara. Brasil Escola. Disponível em: https://brasilescola.uol.com.br/folclore/lendas-', 'Iara, uma jovem e encantadora guerreira, era filha do Pajé da aldeia. Forte, inteligente e de canto único, vivia sendo elogiada pelo pai.\r\n\r\nSeus dois irmãos tinham muita inveja. Juntos, planejaram dar um fim à filha do Pajé. Ao frio da noite e à luz da Lua, eles a atacaram de surpresa! Mas a jovem era uma excelente guerreira e percebeu.\r\n\r\nFuriosa e impiedosa, ela lutou com os irmãos. Ao perceber que havia matado os filhos do Pajé, Iara fugiu para a mata temendo ser castigada. Até que foi encontrada por guerreiros da aldeia e, às ordens do pai, foi jogada no rio.\r\n\r\nAs águas a abraçaram e ela afundou, afundou. Iara achava que sua vida tinha chegado ao fim. Mas, de repente, sentiu que subia. Alguns peixes estavam levando Iara para a superfície!\r\n\r\nEm um ato de pena e compaixão da Lua, Iara foi transformada em uma criatura meio peixe, meio mulher.\r\n\r\nAgora, vivia no rio. Ali, todas as tardes, cantava. Seu canto seduzia pescadores, guerreiros desavisados. Enfeitiçados pela criatura, entravam no rio, de onde nunca mais saíam.', 3, 1),
('Iara: la Madre del Agua', 'Leyenda: Sirena Iara. Escola do Brasil. Disponible en: https://brasilescola.uol.com.br/folclore/lend', 'Iara, una joven y encantadora guerrera, era hija del chamán de la aldea. Su padre constantemente la alababa por su fuerza, inteligencia y canto único.\r\n\r\nSus dos hermanos le tenían mucha envidia y, juntos, planearon acabar con la vida de la muchacha. ¡En una noche fría y oscura, le tendieron una emboscada! Pero la joven, al ser una excelente guerrera, se dio cuenta rápidamente.\r\n\r\nLuchó con gran fuerza y valentía contra sus hermanos. Al percatarse de que los había matado, Iara huyó hacia la selva por temor a ser castigada por el chamán. Tiempo después, los guerreros de la aldea la atraparon y, por orden de su padre, la arrojaron al río.\r\n\r\nLas aguas la envolvieron y ella se hundió cada vez más profundo. Iara creyó que su vida había acabado allí, pero, de repente, sintió que ascendía. ¡Unos peces la llevaban hacia la superficie!\r\n\r\nEn un acto de piedad y compasión, la Luna convirtió a Iara en una criatura mitad pez y mitad mujer. Así, podría vivir tranquila en el río.\r\n\r\nDesde entonces, vivió en el agua y, cada tarde, entonaba sus cantos. Su voz seducía a los pescadores y a los guerreros desprevenidos. Embrujados por la criatura, se adentraban en el río, de donde nunca más volverían a salir.', 3, 2),
('Piye: kam yikam pain kom', 'Legenda: Sereia Iara. Brasil Escola. Disponível em: https://brasilescola.uol.com.br/folclore/lendas-', 'Whem ,xoyam na narima Ko ratakana ,piye neim aldeia na quem''.hatakana'' tamana quem,ak i'' ma e na e'' ne quem  kon'' kote kama'' quem ''.\r\n\r\nXerequem iri na ne miya''  ka nokon kakam nonon'' ka xi arak'' Kakam''. Miya'' nana, ara pan nanain'' ka ara'' xi kaka ''wixikam'' piye pain ''oro ara'' wao''.pain'' ka xin'' nein'' xim'' kom Narain'' nukun panawo'',pain ma iri na ne quep'' ak kakam na! Xoyam iri'' na ne taxi'' ak ka kama'' na pain'' ka noro ''kakam'' ak i'' ma'' na''.\r\n\r\nMo'' xa'' mam ''ak ka kama ''na,hatakana'' tamana'' na quem'' kokon'' xerequem''.pain'' ma'' iri na'' ne''ta xi'' ak ka kama'' na,mo'' xa'' m''am'''' aka ka na'' ma'' whem ''''quem'', pain '' m''a '' iri'' na ne '' mam ak ka kama'' na'' xik mam'''' nanam'''' pain '' kote'' ne '' kom''''íam.'' pain'' toparapa'' pin kon pan xi ka , hwem'' iri''na'' ne.\r\n\r\nPain'' ma'' iri na'' ne''ta,pa '' ak ne''na kote'' kom'''' pan '' k''oromam''ak kama'' na'' xoyam.whem iri na mi ''tara''''ma ak ka kana,e'' ak kama'' na'', xoyam ''tá xi '' ak kama'' na'' xoyam ''.noro'' ak kama'' na'' wham'''' an mam''''  ak ka kana wham ''''quem''''.\r\n\r\nAk'' i ma'' ak'' ne '' ta'' noro ''ak'' kam'' na'' xoyam ''panawo'' ta''.whem''ma'' iri na'' ne''ta wham ak'' kama'' na'' xoyam'' '' ma''an  ma''''  nanam  narima .\r\n\r\nWari nem kom pin ak'' kama'' na'' xoyam  ma'''',pain oro iri Win, tama'' kom ''xi pa na'''', pain'' oro ka ''ne'' quen xoyam ma'' ak'' i ma'' e'' ta'' oro kanarine'',pe'' tohken ak'' kama'' na'' pain'' kom ta'' iri''o'' tara''.', 3, 3),
('O Boto-cor-de-rosa', 'Legenda: As aparências do Boto-cor-de-rosa. Toda Matéria. Disponível em: https://www.todamateria.com', 'Em dias da festa, como São João e Santo Antônio, humanos e encantados celebram e se divertem.\r\n\r\nO Boto sai das profundezas dos rios durante uma noite estrelada. A cauda dá lugar a pés viscosos, as \r\nbarbatanas se transformam em longos braços. \r\n\r\nPouco a pouco, o animal vira um lindo rapaz. Com a pele rosada e um buraco no topo da cabeça, o estranho homem pega roupas e um chapéu para vestir.\r\n\r\nHoras depois, lá este ele no meio das cidades, aproveitando bailes e festas. Seu charme atrai belas jovens. Com muita esperteza e muita sedução, ele as leva para o rio, “para um passeio de barco”.\r\n\r\nO final é o mesmo: no dia seguinte, a moça acorda sozinha! Próximo à beira do rio, um Boto grande e brilhoso rodopia e nada contente pelas águas.\r\n\r\nO misterioso homem nunca mais é visto pela jovem seduzida e nove meses depois, nasce um filho, fruto de uma noite de amor e aventura.', 4, 1),
('El bufeo', 'Leyenda: Las apariciones del delfín rosado. Toda Matéria. Disponible en: https://www.todamateria.com', 'En días de fiesta, como San Juan y San Antonio, los humanos y los seres encantados celebran y se divierten.\r\n\r\nEl bufeo sale de las profundidades de los ríos durante una noche estrellada. Su cola se convierte en pies viscosos y sus aletas, en largos brazos.\r\n\r\nPoco a poco, el animal se transforma en un apuesto joven. Con la piel rosada y un hueco en el tope de la cabeza, este extraño hombre toma ropa y un sombrero para vestirse.\r\n\r\nHoras más tarde, ya está en la ciudad disfrutando de bailes y festejos. Su encanto atrae a hermosas jóvenes y, con gran astucia y mucha seducción, las lleva al río \"para dar un paseo en barco\".\r\n\r\nEl final es siempre el mismo: al día siguiente, ¡la joven despierta sola! Y, cerca de la orilla del río, un bufeo grande y brillante da vueltas y nada alegremente por las aguas.\r\n\r\nLa joven seducida no vuelve a ver jamás al misterioso hombre y, nueve meses después, nace un hijo, fruto de una noche de amor y aventura.', 4, 2),
('Pain'' kahain- ma'' to o ''xirak', 'Legenda: As aparências do Boto-cor-de-rosa. Toda Matéria. Disponível em: https://www.todamateria.com', 'Pain'' ka'' ma'' pi xiram wa'' ,pain'' xijein ''Ka'' to ''wa'',tarama'' Ko karawa yimam'' quek te'' tama''na'' pain'' to'' Ka ''.\r\n\r\nPain'' ma''iri na'' ne''ta main'' ak'' Kai '' na'' kom '' pain'' xim''noro ak'' kon  na'' piyo pain'' pawi'''' quem'' . pain'' ka'' pe'' pan nu kuk'',an''\r\nquep'' ak kon na'' pain'' taparakom''quem'' .\r\n\r\nAk i'' ma'' e ''pain'' tomi xuk'' ta'' , tarama'' Ko awi tamana'' '' ak'' Ka xohra ma''iri ''om Ka ya''ya tamana'' nonon oro narima nukun quem'' pe'' pan na'' wohri quem'' Ka ''na'' \r\n\r\nXoxek pin iri'' na ne,mao ak kain na xijein ''xirim'' pain ka ''ara ''to wa oro ka quek'''' te'' WA''.\r\niri'' tarama'' Ko aw''i tamana'' na quem'' . xuk'' ta'' tarama'' ak'' Ka na'' ne''ta kom'',pain ''ka'' xuk'' nuk'' tramaxikon\"\r\n\r\nKorom mao'' ho'' ak kain na xirinain ka'' ya'' to wa kom piwa ka'' .korom hwet ak kon na kem ''.Kep ak'' kain na'' kaximakon piwa awo'' wa! Kerek te tamana'' na awo'' pain'' Ka kep kon piwa\r\n\r\nAk i'' ma'' na quek tokwa tarama'' Ko kahain ta'' oro xere'' xohra Ko awi tamana'' na Ko ma ta'', pain'' pin iri'' na ne ma pin ak kon na piye kem ''.', 4, 3),
('\"Ekeko\": o Deus da abundância', 'Legenda: Boneco Ekeko. Wikimedia Commons. Disponível em: https://commons.wikimedia.org/wiki/File:Eke', 'Na cidade de La Paz, vivia um homem aimada chamado Iqiqu. Era pequeno, gordo, de bigode ralo. Usava poncho e chullo tipicamente andinos. \r\n\r\nNaquela época, era muito difícil chegar comida à região. As pessoas estavam morrendo de fome, incluindo sua namorada. Então, para evitar o sofrimento da amada, Iqiqu contrabandeava alguns produtos - daí surge a fama de riqueza e abundância ao redor de sua figura.\r\n\r\nAcredita-se que o que você ofertar ao \"Ekeko\", ele vai retribuir. Por isso, suas estátuas são colocadas nas casas e, geralmente, rodeadas de dinheiro.', 5, 1),
('Ekeko: el dios de la abundancia', 'Leyenda: Muñeco Ekeko. Wikimedia Commons. Disponible en: https://commons.wikimedia.org/wiki/File:Eke', 'En la ciudad de La Paz vivía un hombre aimara llamado Iqiqu. Era pequeño, gordo y tenía un bigote ralo. Llevaba un poncho y un chullo, prendas típicamente andinas.\r\n\r\nEn aquella época, era muy difícil que llegaran alimentos a la región. La gente moría de hambre y su novia penaba. Entonces, para evitar el sufrimiento de su amada, Iqiqu contrabandeaba productos y suministros; de ahí surge la fama de riqueza y abundancia que rodea a su figura.\r\n\r\nSe cree que lo que uno le ofrezca al Ekeko, él se lo concederá. Por eso, sus estatuillas se colocan en los hogares, generalmente rodeadas de dinero.', 5, 2),
('To'' o'' :wiri ''ko'' howa''kama'' quem''', 'Leyenda: Muñeco Ekeko. Wikimedia Commons. Disponible en: https://commons.wikimedia.org/wiki/File:Eke', '''Pain'' ka'' pe'' ka main'' ''oro wiyam'', pain''pe'' ka'' main'' Kai iri'' na ne taxi'' ak kama'' na'' pain'' ka'' tomi \r\ntaxi'' pa'' nanam quem'' ak'' kama'' na'' xoyam ma'' quem'' ta'' oro kanarine ''\r\n\r\nPain'' ka'' ra‘pane '' , miya'' na'' Ka I na na'' ne''ka Tam ''ne'' oro ''''karawa ''''pain pira ''.KokoN oro xuk'' oro wari quem'' na'',kono''taxi'' nana'' oro wari quem'' pain ka pe'' nukut '' kana'',an to'' pin ''ta'' xi pa nanam '' oro narima ''nukun quem'' na''.pain'' ka ''ta'' ya''paxi'' kakam'' narima nukun quem'' pain iri'' na ne quep'' ak kama'' na'' xoyam ma'' quem'' to'' e ''ak'' kama'' na'' xik.\r\n\r\nHowa'' xin'' ka '' tomi'' ne''quem'' to'' o'' ma'' quem'' , ara'' xi yei '' ma'' quem'' . ak'' i ma'' na '',pe '' ho '' nem pain'' mu''i ye'' xirim '' nem'' ka na, ye'' oro xijein quem'', ye'' kayi'' tam''quem''.', 5, 3),
('O Duende da Mata', 'Legenda: Duende. Wikipédia. Disponível em: https://es.wikipedia.org/wiki/Archivo%3AEl_duende_-_Leyen', 'Contam os mais velhos que, nas profundezas das matas benianas, vive um ser de aparência desfigurada e enrugada, cujos pés são virados para trás.\r\n\r\nO duende era, originalmente, uma criatura protetora da floresta; contudo, a caça e o desmatamento causados pelo homem o transformaram em uma criatura rancorosa e vingativa. Ele rouba ferramentas, manipula trilhas e emite sons que atormentam os caçadores, deixando-os desorientados na mata.\r\n\r\nNem as crianças escapam dele. Com seu grande chapéu de palha que lhe cobre o rosto, ele se aproxima delas fingindo ser um idoso.\r\n\r\nQuando se depara com meninos malcriados, ele os engana, dizendo estar perdido, e então os leva para dentro da mata, de onde raramente retornam. E os obedientes? Bem, o duende brinca com eles e, ao anoitecer, leva-os de volta para casa e os põe para dormir.\r\n\r\nQuem se depara com o duende jamais volta a ser o mesmo.', 6, 1),
('El Duende del Monte', 'Leyenda: Duende. Wikipedia. Disponible en: https://es.wikipedia.org/wiki/Archivo%3AEl_duende_-_Leyen', 'Se dice que en los adentros del monte beniano vive un ser pequeño y deforme, cuyas facciones son retorcidas y sus pies, volcados.\r\n\r\nEl duende era una simple criatura protectora del bosque; sin embargo, la caza y la deforestación del hombre lo convirtieron en un ser rencoroso y vengativo. Él roba herramientas, cambia los caminos y emite sonidos que atormentan a los cazadores, dejándolos perdidos en el bosque.\r\n\r\nNi los niños escapan de él. Con su gran sombrero de paja, que le cubre la cara, se acerca a ellos fingiendo ser un anciano. Con la excusa de estar perdido, se lleva a los malcriados y atrevidos al monte, de donde rara vez regresan. ¿Y los obedientes? Dicen que él se pone a jugar con ellos y, al anochecer, los lleva a sus casas y los adormece con su canto.\r\n\r\nQuien se cruce con el duende, jamás vuelve a ser el mismo.', 6, 2),
('O Touro de San Borja', 'Legenda: O Touro de San Borja. Ilustração representativa da lenda. Fonte: Elaborada por inteligência', 'Dizem que, há mais de um século, na cidade de San Borja, vivia um fazendeiro cruel e violento. Ele chicoteava e maltratava constantemente seus peões. Seu nome era Julián.\r\n\r\nO velho gritava com as pessoas e as agredia por qualquer motivo. Sua ira e impaciência eram tamanhas que sua simples presença deixava em alerta os trabalhadores e moradores da região.\r\n\r\nContudo, numa noite de tempestade, a maldade do senhor Julián chegou ao fim. Um raio forte atingiu sua residência. Um trovão profundo ressoou por todo o céu cinzento. A casa, feita quase inteiramente de madeira, foi rapidamente consumida pelas chamas.\r\n\r\nO velho acordou assustado com os gritos e o cheiro intenso de fumaça. Mas já era tarde demais. Não havia escapatória para ele. Todos que estavam perto da fazenda puderam ouvir os gritos de desespero e os pedidos de socorro. Mas ninguém foi ajudá-lo.\r\n\r\nNo dia seguinte à tempestade, restava pouco daquela fazenda majestosa e imponente. Seu dono foi reduzido a um pedaço de carvão.\r\n\r\nOs deuses, como castigo por sua maldade e crueldade, condenaram sua alma a nunca encontrar paz e a permanecer vagando pela terra. O espírito, carregado de ódio e rancor, assumiu a forma de um touro grande, de pelagem escura, olhos vermelhos, chifres afiados e correntes nas patas traseiras.\r\n\r\nDizem que, em locais marcados por profunda injustiça, surge um touro de aspecto macabro, que vaga em busca de alguém para matar e, assim, saciar sua sede de sangue e vingança.', 7, 1),
('El Toro de San Borja', 'Leyenda: El Toro de San Borja. Ilustración representativa de la leyenda. Fuente: Elaborada mediante', 'Se dice que, hace más de un siglo, en la ciudad de San Borja, vivía un hacendero cruel y violento. Chicoteaba y maltrataba constantemente a sus peones. Su nombre era Julián.\r\n\r\nEl viejo le gritaba y le pegaba a la gente por cualquier razón. Su ira e impaciencia eran tamañas que su mera presencia ponía en alerta a los trabajadores y pobladores de la región.\r\n\r\nSin embargo, una noche de tempestad, la maldad del señor Julián tuvo un fin. Un fuerte rayo cayó en su residencia. Un trueno profundo resonó por todo el cielo gris. La casa, casi toda de madera, rápidamente ardió en llamas.\r\n\r\nEl viejo se despertó asustado con los gritos y el intenso olor a humo. Pero ya era muy tarde. No había escapatoria para él. Todos los que estaban cerca de la hacienda pudieron oír los gritos de desesperación y los clamores de ayuda. Pero nadie acudió a socorrerlo.\r\n\r\nAl día siguiente de la tormenta, quedaba poco de la hacienda majestuosa e imponente. Su dueño fue reducido a un trozo de carne chamuscada.\r\n\r\nLos dioses, como castigo por sus acciones violentas y crueles, condenaron su alma a nunca tener paz y a permanecer vagando en la tierra. El espíritu, cargado de odio y rencor, tomó la forma de un toro grande, de pelaje oscuro, ojos rojos, cuernos afilados y corrientes en sus patas traseras.\r\n\r\nSe dice que, en lugares de profunda injusticia, surge un toro de aspecto macabro, que vaga en busca de alguien a quien matar y así saciar su sed de sangre y venganza.', 7, 2);

